package com.greenocean.backend.listener.planning;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import static com.greenocean.backend.listener.planning.ListenerSupportPolicy.*;
@Service @Transactional(readOnly=true) public class ListenerSupportOperations {
 private final ListenerSupportPolicy p;private final ListenerSupportRetention retention;
 public ListenerSupportOperations(ListenerSupportPolicy p,ListenerSupportRetention retention){this.p=p;this.retention=retention;}
 public void staff(UUID actor){if(!p.truth("SELECT EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.id=? AND u.status='ACTIVE' AND r.name IN('ADMIN','MODERATOR'))",actor))throw denied(403,"STAFF_REQUIRED","Current staff authority is required.");}
 public List<Map<String,Object>> listeners(UUID actor,UUID after){staff(actor);return p.db.queryForList("SELECT l.user_id AS id,pr.display_name FROM listener_profiles l JOIN profiles pr ON pr.user_id=l.user_id WHERE live_listener_qualified(l.user_id) AND(?::uuid IS NULL OR l.user_id>?) ORDER BY l.user_id LIMIT 50",after,after);}
 public Map<String,Object> dashboard(UUID actor){staff(actor);var result=new LinkedHashMap<String,Object>();result.put("serverTime",p.now());result.put("options",p.options());result.put("queueCounts",p.db.queryForList("SELECT status,count(*) AS count FROM listener_wait_queue WHERE status IN('WAITING','OFFERED') OR updated_at>listener_support_now()-INTERVAL '24 hours' GROUP BY status ORDER BY status"));result.put("bookingCounts",p.db.queryForList("SELECT status,count(*) AS count FROM listener_bookings WHERE starts_at BETWEEN listener_support_now()-INTERVAL '24 hours' AND listener_support_now()+INTERVAL '24 hours' GROUP BY status ORDER BY status"));result.put("readyListeners",p.db.queryForObject("SELECT count(*) FROM listener_presence WHERE live_listener_ready(listener_id)",Long.class));result.put("activePlannedSessions",p.db.queryForObject("SELECT count(*) FROM live_support_requests WHERE planned_seconds IS NOT NULL AND status IN('ACTIVE','INTERRUPTED')",Long.class));result.put("workers",p.db.queryForList("SELECT name,last_success_at FROM listener_support_worker_state ORDER BY name"));result.put("alertsConfigured",false);result.put("retention",retention.report());var alerts=new ArrayList<String>();if(p.queue()&&p.db.queryForObject("SELECT count(*) FROM listener_wait_queue WHERE status='WAITING'",Long.class)>0&&p.db.queryForObject("SELECT count(*) FROM listener_presence WHERE live_listener_ready(listener_id)",Long.class)==0)alerts.add("WAITING_WITHOUT_READY_LISTENER");if(p.db.queryForObject("SELECT count(*) FROM live_support_requests WHERE status IN('ACTIVE','INTERRUPTED') AND planned_ends_at<=listener_support_now()",Long.class)>0)alerts.add("PLANNED_DEADLINE_RECONCILIATION_DUE");if(!p.truth("SELECT EXISTS(SELECT 1 FROM listener_support_worker_state WHERE name='planning-maintenance' AND last_success_at>listener_support_now()-INTERVAL '1 minute')"))alerts.add("MAINTENANCE_NOT_RECENTLY_OBSERVED");result.put("alertConditions",alerts);return result;}
}
